{
  "caproverOneClickApp": {
    "description": "Realtime collaborative Markdown notes on all platforms",
    "displayName": "CodiMD",
    "documentation": "https://hackmd.io/c/codimd-documentation",
    "instructions": {
      "end": "Aaaand you're done! \ud83d\ude04\n\nYour service is available as $$cap_appname",
      "start": "Realtime collaborative Markdown notes on all platforms.\n\nGitHub: https://github.com/hackmdio/codimd"
    },
    "isOfficial": true,
    "variables": [
      {
        "defaultValue": "$$cap_gen_random_hex(16)",
        "description": "Password to connect to the database",
        "id": "$$cap_DB_PASS",
        "label": "Database Password"
      },
      {
        "defaultValue": "Europe/London",
        "description": "This is the timezone for the application, find yours at https://en.wikipedia.org/wiki/List_of_tz_database_time_zones",
        "id": "$$cap_timezone",
        "label": "Timezone"
      }
    ]
  },
  "captainVersion": 4,
  "services": {
    "$$cap_appname": {
      "caproverExtra": {
        "containerHttpPort": "3000"
      },
      "environment": {
        "DB_HOST": "srv-captain--$$cap_appname-mariadb",
        "DB_NAME": "codimd",
        "DB_PASS": "$$cap_DB_PASS",
        "DB_PORT": 3306,
        "DB_USER": "codimd",
        "PGID": 1000,
        "PUID": 1000,
        "TZ": "$$cap_timezone"
      },
      "image": "linuxserver/codimd:1.6.0-ls44",
      "restart": "always",
      "volumes": [
        "$$cap_appname-config:/config"
      ]
    },
    "$$cap_appname-mariadb": {
      "caproverExtra": {
        "notExposeAsWebApp": "true"
      },
      "environment": {
        "MYSQL_DATABASE": "codimd",
        "MYSQL_PASSWORD": "$$cap_DB_PASS",
        "MYSQL_ROOT_PASSWORD": "$$cap_DB_PASS",
        "MYSQL_USER": "codimd",
        "PGID": 1000,
        "PUID": 1000,
        "TZ": "$$cap_timezone"
      },
      "image": "linuxserver/mariadb:110.4.14mariabionic-ls77",
      "volumes": [
        "$$cap_appname-mariadb-config:/config"
      ]
    }
  }
}
